}
"}

{"path": "/tmp/sv-cceffff6a3db42cb8bee67f4e8271c95/Components/Pages/Settings/SecuritySection.razor", "file_text": "@inject ISettingsService SettingsService

@if (isLoading)
{
    <p>Loading security settings...</p>
}
else if (settings is not null)
{
    <section class="settings-section">
        <h2>Security</h2>

        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-toggle" @onclick="() => showPasswordPanel = !showPasswordPanel">
                @(showPasswordPanel ? "▼" : "▶") Change Password
            </button>

            @if (showPasswordPanel)
            {
                <div class="panel-content">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>

                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>

                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="error-message">@passwordError</div>
                    }

                    @if (passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }

                    <button class="btn-primary" @onclick="UpdatePassword" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="status-row">
                <span class="status-indicator @(settings.TwoFactorEnabled ? "enabled" : "disabled")">
                    @(settings.TwoFactorEnabled ? "● Enabled" : "○ Disabled")
                </span>
            </div>
            @if (settings.LastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("MMM dd, yyyy HH:mm")</td>
                            <td>
                                @if (session != settings.Sessions.FirstOrDefault())
                                {
                                    <button class="btn-danger btn-small"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay">
                <div class="dialog">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn-danger" @onclick="RevokeSession" disabled="@isRevoking">
                            @(isRevoking ? "Revoking..." : "Revoke")
                        </button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>
}

@code {
    private SecuritySettings? settings;
    private bool isLoading = true;

    // Password change state
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;
    private bool isChangingPassword;

    // Session revocation state
    private ActiveSession? sessionToRevoke;
    private bool isRevoking;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        settings = await SettingsService.GetSecuritySettingsAsync();
        isLoading = false;
    }

    private async Task UpdatePassword()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password cannot be empty.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "Passwords do not match.";
            return;
        }

        isChangingPassword = true;

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke is null) return;

        isRevoking = true;

        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        settings = await SettingsService.GetSecuritySettingsAsync();
        sessionToRevoke = null;

        isRevoking = false;
    }
}
"}

{"path": "/tmp/sv-cceffff6a3db42cb8bee67f4e8271c95/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@inject ISettingsService SettingsService

@if (isLoading)
{
    <p>Loading appearance settings...</p>
}
else
{
    <section class="settings-section">
        <h2>Appearance</h2>

        <!-- Theme Selector -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label>
                    <input type="radio" name="theme" value="Light"
                           checked="@(theme == "Light")"
                           @onchange="() => theme = &quot;Light&quot;" />
                    Light
                </label>
                <label>
                    <input type="radio" name="theme" value="Dark"
                           checked="@(theme == "Dark")"
                           @onchange="() => theme = &quot;Dark&quot;" />
                    Dark
                </label>
                <label>
                    <input type="radio" name="theme" value="System"
                           checked="@(theme == "System")"
                           @onchange="() => theme = &quot;System&quot;" />
                    System
                </label>
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label>
                    <input type="radio" name="fontSize" value="Small"
                           checked="@(fontSize == "Small")"
                           @onchange="() => fontSize = &quot;Small&quot;" />
                    Small
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Medium"
                           checked="@(fontSize == "Medium")"
                           @onchange="() => fontSize = &quot;Medium&quot;" />
                    Medium
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Large"
                           checked="@(fontSize == "Large")"
                           @onchange="() => fontSize = &quot;Large&quot;" />
                    Large
                </label>
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <label class="toggle-row">
            <input type="checkbox" @bind="compactMode" />
            <span>Compact Mode</span>
        </label>

        <!-- Live Preview -->
        <div class="live-preview @GetPreviewClasses()">
            <h4>Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p><strong>Theme:</strong> @theme | <strong>Font:</strong> @fontSize | <strong>Language:</strong> @language</p>
            @if (compactMode)
            {
                <p><em>Compact mode is enabled — reduced spacing and margins.</em></p>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save")
            </button>
        </div>

        @if (showSuccessMessage)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    </section>
}

@code {
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccessMessage;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetAppearanceAsync();

        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;

        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{theme.ToLowerInvariant()} preview-font-{fontSize.ToLowerInvariant()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        isSaving = true;

        var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(updated);

        isSaving = false;
        showSuccessMessage = true;
        _ = HideSuccessMessage();
    }

    private async Task HideSuccessMessage()
    {
        await Task.Delay(3000);
        showSuccessMessage = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

