@inject ISettingsService SettingsService

@if (isLoading)
{
    <p>Loading appearance settings...</p>
}
else
{
    <section class="settings-section">
        <h2>Appearance</h2>

        <!-- Theme Selector -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label>
                    <input type="radio" name="theme" value="Light"
                           checked="@(theme == "Light")"
                           @onchange="() => theme = &quot;Light&quot;" />
                    Light
                </label>
                <label>
                    <input type="radio" name="theme" value="Dark"
                           checked="@(theme == "Dark")"
                           @onchange="() => theme = &quot;Dark&quot;" />
                    Dark
                </label>
                <label>
                    <input type="radio" name="theme" value="System"
                           checked="@(theme == "System")"
                           @onchange="() => theme = &quot;System&quot;" />
                    System
                </label>
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label>
                    <input type="radio" name="fontSize" value="Small"
                           checked="@(fontSize == "Small")"
                           @onchange="() => fontSize = &quot;Small&quot;" />
                    Small
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Medium"
                           checked="@(fontSize == "Medium")"
                           @onchange="() => fontSize = &quot;Medium&quot;" />
                    Medium
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Large"
                           checked="@(fontSize == "Large")"
                           @onchange="() => fontSize = &quot;Large&quot;" />
                    Large
                </label>
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="language">
                <option value="en">English</option>
                <option value="es">Spanish</option>
                <option value="fr">French</option>
                <option value="de">German</option>
                <option value="ja">Japanese</option>
                <option value="zh">Chinese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <label class="toggle-row">
            <input type="checkbox" @bind="compactMode" />
            <span>Compact Mode</span>
        </label>

        <!-- Live Preview -->
        <div class="live-preview @GetPreviewClasses()">
            <h4>Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p><strong>Theme:</strong> @theme | <strong>Font:</strong> @fontSize | <strong>Language:</strong> @language</p>
            @if (compactMode)
            {
                <p><em>Compact mode is enabled — reduced spacing and margins.</em></p>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save")
            </button>
        </div>

        @if (showSuccessMessage)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    </section>
}

@code {
    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccessMessage;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetAppearanceAsync();

        theme = settings.Theme;
        fontSize = settings.FontSize;
        language = settings.Language;
        compactMode = settings.CompactMode;

        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{theme.ToLowerInvariant()} preview-font-{fontSize.ToLowerInvariant()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        isSaving = true;

        var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
        await SettingsService.SaveAppearanceAsync(updated);

        isSaving = false;
        showSuccessMessage = true;
        _ = HideSuccessMessage();
    }

    private async Task HideSuccessMessage()
    {
        await Task.Delay(3000);
        showSuccessMessage = false;
        await InvokeAsync(StateHasChanged);
    }
}

@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }
}

