namespace sv_cceffff6a3db42cb8bee67f4e8271c95;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

.settings-dashboard {
    display: flex;
    min-height: 600px;
    gap: 2rem;
    padding: 1rem;
}

/* Sidebar */
.settings-sidebar nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    min-width: 180px;
}

.settings-sidebar nav ul li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    border-radius: 6px;
    margin-bottom: 0.25rem;
    transition: background-color 0.2s;
}

.settings-sidebar nav ul li:hover {
    background-color: #f0f0f0;
}

.settings-sidebar nav ul li.active {
    background-color: #0d6efd;
    color: white;
    font-weight: 600;
}

/* Content area */
.settings-content {
    flex: 1;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
}

/* Form groups */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background-color: #0d6efd;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background-color: #6c757d;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-danger {
    background-color: #dc3545;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
}

.btn-small {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

/* Toast */
.toast.success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background-color: #d1e7dd;
    color: #0f5132;
    border-radius: 4px;
    border: 1px solid #badbcc;
}

/* Toggle rows */
.toggle-group,
.muted-channels {
    margin-bottom: 1rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-preview img {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #ddd;
}

.avatar-url {
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.5rem;
}

/* Security */
.expandable-panel {
    margin-bottom: 1.5rem;
    border: 1px solid #ddd;
    border-radius: 6px;
}

.panel-toggle {
    width: 100%;
    padding: 0.75rem 1rem;
    background: none;
    border: none;
    text-align: left;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid #eee;
}

.error-message {
    color: #dc3545;
    margin-bottom: 0.75rem;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.status-indicator.enabled {
    color: #198754;
    font-weight: 600;
}

.status-indicator.disabled {
    color: #6c757d;
}

.info-text {
    font-size: 0.85rem;
    color: #666;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid #eee;
    text-align: left;
}

.sessions-table th {
    font-weight: 600;
    background-color: #f8f9fa;
}

.current-badge {
    font-size: 0.8rem;
    background-color: #e2e3e5;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
}

.dialog h4 {
    margin-top: 0;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-weight: normal;
    cursor: pointer;
}

/* Appearance preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 2px dashed #ccc;
    border-radius: 8px;
}

.live-preview.preview-theme-dark {
    background-color: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.live-preview.preview-theme-light {
    background-color: #ffffff;
    color: #333;
}

.live-preview.preview-font-small {
    font-size: 0.85rem;
}

.live-preview.preview-font-medium {
    font-size: 1rem;
}

.live-preview.preview-font-large {
    font-size: 1.2rem;
}

.live-preview.preview-compact {
    padding: 0.5rem;
    line-height: 1.2;
}

