+    max-width: 400px;
+    width: 90%;
+}
+
+.dialog h4 {
+    margin-top: 0;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+}
+
+/* Radio groups */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+}
+
+.radio-group label {
+    display: flex;
+    align-items: center;
+    gap: 0.35rem;
+    font-weight: normal;
+    cursor: pointer;
+}
+
+/* Appearance preview */
+.live-preview {
+    margin-top: 1.5rem;
+    padding: 1.25rem;
+    border: 2px dashed #ccc;
+    border-radius: 8px;
+}
+
+.live-preview.preview-theme-dark {
+    background-color: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.live-preview.preview-theme-light {
+    background-color: #ffffff;
+    color: #333;
+}
+
+.live-preview.preview-font-small {
+    font-size: 0.85rem;
+}
+
+.live-preview.preview-font-medium {
+    font-size: 1rem;
+}
+
+.live-preview.preview-font-large {
+    font-size: 1.2rem;
+}
+
+.live-preview.preview-compact {
+    padding: 0.5rem;
+    line-height: 1.2;
+}
